/**
 * Unit tests for DeserializationContext#instantiationException.
 */
public class DeserializationContext_instantiationException_TriageGen1Test {

    @Mock
    private JsonParser _parser;

    @Mock
    private BeanSerializerFactory _factory;

    private DeserializationContext _context;
    private TypeFactory _typeFactory;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        _typeFactory = TypeFactory.defaultInstance();

        // DeserializationContext is abstract/protected, we use a subclass or a mock.
        // Since we need to trigger constructType and access _parser, 
        // we use a concrete implementation via a mock or a test-subclass.
        // Given the signature, we can mock the context or use a real one if possible.
        // Here we use a mock to satisfy the dependency injection of the constructor.
        _context = new DeserializationContext(_factory) {
            // Overriding to allow access to the protected _parser if necessary, 
            // though the method uses the field directly.
            // In Jackson, DeserializationContext is usually instantiated by ObjectMapper.
        };

        // To allow the method to run, we need to ensure the context is properly initialized.
        // Since we cannot easily instantiate the abstract DeserializationContext with all fields,
        // we use a mock of the context for the test but we must be careful because 
        // the method being tested is the one we are testing.
        // Actually, the best way is to use a real DeserializationContext via a spy or a subclass.

        // Let's create a concrete implementation for testing purposes.
        _context = new TestDeserializationContext(_factory, _parser, _typeFactory);
    }

    private static class TestDeserializationContext extends DeserializationContext {
        private final JsonParser parser;
        private final TypeFactory tf;

        protected TestDeserializationContext(DeserializerFactory df, JsonParser p, TypeFactory tf) {
            super(df);
            this.parser = p;
            this.tf = tf;
        }

        @Override
        public JavaType constructType(Class<?> cls) {
            return tf.constructType(cls);
        }

        @Override
        public JsonParser getParser() {
            return parser;
        }

        // We need to override the field access if the method uses the field _parser directly.
        // Since the method provided uses '_parser', we assume it's a field in the class.
        // In a real test environment, we'd use reflection to set the private field.
    }

    // Because the method uses the field '_parser' directly, we must inject it via reflection 
    // if we use a real instance, or use a Mockito spy.

    @Test
    public void testInstantiationException_WithNullCause() throws Exception {
        Class<?> targetClass = String.class;

        // Use reflection to set the protected _parser field in a real DeserializationContext
        DeserializationContext context = createContextWithParser(_parser);

        JsonMappingException exception = context.instantiationException(targetClass, null);

        assertNotNull(exception);
        assertTrue(exception instanceof InvalidDefinitionException);
        // When cause is null, msg should contain "problem: N/A"
        assertTrue(exception.getMessage().contains("problem: N/A"));
        assertTrue(exception.getMessage().contains("String"));
    }

    @Test
    public void testInstantiationException_WithCauseAndMessage() throws Exception {
        Class<?> targetClass = Integer.class;
        Throwable cause = new RuntimeException("Specific Error");

        DeserializationContext context = createContextWithParser(_parser);

        JsonMappingException exception = context.instantiationException(targetClass, cause);

        assertNotNull(exception);
        assertTrue(exception.getMessage().contains("problem: Specific Error"));
        assertEquals(cause, exception.getCause());
    }

    @Test
    public void testInstantiationException_WithCauseAndNullMessage() throws Exception {
        Class<?> targetClass = Double.class;
        // A Throwable that returns null for getMessage()
        Throwable cause = new Throwable() {
            @Override
            public String getMessage() {
                return null;
            }
        };

        DeserializationContext context = createContextWithParser(_parser);

        JsonMappingException exception = context.instantiationException(targetClass, cause);

        assertNotNull(exception);
        // When cause.getMessage() is null, it uses ClassUtil.nameOf(cause.getClass())
        // which for this anonymous class will be something like "...$1" or the class name.
        assertTrue(exception.getMessage().contains("problem:"));
        assertEquals(cause, exception.getCause());
    }

    /**
     * Helper to instantiate DeserializationContext and inject the protected _parser field via reflection.
     */
    private DeserializationContext createContextWithParser(JsonParser parser) throws Exception {
        // We use the constructor: protected DeserializationContext(DeserializerFactory df);
        DeserializationContext context = new DeserializationContext(_factory) {
            @Override
            public JavaType constructType(Class<?> cls) {
                return TypeFactory.defaultInstance().constructType(cls);
            }
        };

        java.lang.reflect.Field parserField = DeserializationContext.class.getDeclaredField("_parser");
        parserField.setAccessible(true);
        parserField.set(context, parser);

        return context;
    }
}
